	/**
	 * Method to retrieve the WorkCenter via WorkCenterFetchOneSummary
	 * @param 	summary WorkCenterFetchOneSummary
	 * @return 	WorkCenterFetchOneResponse
	 */
	public WorkCenter getWorkCenter( WorkCenterFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "WorkCenterFetchOneSummary arg cannot be null" );

		WorkCenter entity = null;
		UUID id = summary.getWorkCenterId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a WorkCenter using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


